draw:
var g = p.gravity, v0 = p.speed;
var hDrop = 45;
var pad = 30;
var maxX = Math.max(v0 * Math.sqrt(2 * hDrop / g) * 1.25, 20);
var sx = (W - pad * 2) / maxX;
var sy = (H - pad * 2) / (hDrop * 1.12);
function X(x) { return pad + x * sx; }
function Y(y) { return H - pad - y * sy; }

var tFall = Math.sqrt(2 * hDrop / g);
var now = t % (tFall + 0.8);
var cur = Math.min(now, tFall);
var yNow = hDrop - 0.5 * g * cur * cur;
var xNow = v0 * cur;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// ground
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillText("ground", W - 54, Y(0) + 15);

// equal-height tie line
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(yNow)); ctx.lineTo(X(xNow), Y(yNow)); ctx.stroke();
ctx.setLineDash([]);

// dropped ball path
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(X(0), Y(hDrop)); ctx.lineTo(X(0), Y(0)); ctx.stroke();
ctx.setLineDash([]);

// launched ball full path
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (var s = 0; s <= tFall; s += tFall / 100) {
  var xx = v0 * s, yy = hDrop - 0.5 * g * s * s;
  if (s === 0) ctx.moveTo(X(xx), Y(yy)); else ctx.lineTo(X(xx), Y(yy));
}
ctx.stroke();
ctx.setLineDash([]);

// balls
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(X(0), Y(yNow), 5, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(xNow), Y(yNow), 5, 0, Math.PI * 2); ctx.fill();

// labels
ctx.fillStyle = C.figure;
ctx.fillText("dropped", X(0) + 8, Y(hDrop) - 8);
ctx.fillStyle = C.accent;
ctx.fillText("launched sideways", X(0) + 8, Y(hDrop) - 24);
ctx.fillStyle = C.ink;
ctx.fillText("same height, always", X(0) + 8, Y(yNow) - 9);

out.note = "t = " + cur.toFixed(2) + " s, height " + yNow.toFixed(1) + " m for BOTH balls, horizontal gap " + xNow.toFixed(1) + " m";

var g = 9.8;
var v0 = p.speed;
var th = p.angle * Math.PI / 180;
var ph = p.slope * Math.PI / 180;

// time to land on the line y = x tan(phi)
var num = 2 * v0 * (Math.sin(th) - Math.cos(th) * Math.tan(ph));
var tLand = num / g;
var valid = tLand > 0.05;
if (!valid) tLand = 0.6;

var xL = v0 * Math.cos(th) * tLand;
var yL = v0 * Math.sin(th) * tLand - 0.5 * g * tLand * tLand;
var L = xL / Math.cos(ph);

var pad = 34;
var xs = [0, xL], ys = [0, yL];
for (var s = 0; s <= tLand; s += tLand / 40) {
  xs.push(v0 * Math.cos(th) * s);
  ys.push(v0 * Math.sin(th) * s - 0.5 * g * s * s);
}
var xmin = 0, xmax = 1, ymin = 0, ymax = 1;
for (var i = 0; i < xs.length; i++) {
  if (xs[i] > xmax) xmax = xs[i];
  if (xs[i] < xmin) xmin = xs[i];
  if (ys[i] > ymax) ymax = ys[i];
  if (ys[i] < ymin) ymin = ys[i];
}
xmax = xmax * 1.1 + 2;
xmin = xmin * 1.1 - 2;
ymax = ymax * 1.2 + 2;
ymin = ymin * 1.2 - 2;
var sx = (W - pad * 2) / (xmax - xmin);
var sy = (H - pad * 2) / (ymax - ymin);
var sc = Math.min(sx, sy);
function X(x) { return pad + (x - xmin) * sc; }
function Y(y) { return H - pad - (y - ymin) * sc; }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// horizontal reference
ctx.strokeStyle = C.faint;
ctx.setLineDash([2, 4]);
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
ctx.setLineDash([]);

// the slope itself
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(X(xmin), Y(xmin * Math.tan(ph)));
ctx.lineTo(X(xmax), Y(xmax * Math.tan(ph)));
ctx.stroke();
ctx.lineWidth = 1;

// full trajectory
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath();
for (var s2 = 0; s2 <= tLand; s2 += tLand / 100) {
  var xx = v0 * Math.cos(th) * s2, yy = v0 * Math.sin(th) * s2 - 0.5 * g * s2 * s2;
  if (s2 === 0) ctx.moveTo(X(xx), Y(yy)); else ctx.lineTo(X(xx), Y(yy));
}
ctx.stroke();
ctx.setLineDash([]);

// animated portion
var now = t % (tLand + 0.7);
var cur = Math.min(now, tLand);
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var s3 = 0; s3 <= cur; s3 += tLand / 100) {
  var ax = v0 * Math.cos(th) * s3, ay = v0 * Math.sin(th) * s3 - 0.5 * g * s3 * s3;
  if (s3 === 0) ctx.moveTo(X(ax), Y(ay)); else ctx.lineTo(X(ax), Y(ay));
}
ctx.stroke();
ctx.lineWidth = 1;

var px = v0 * Math.cos(th) * cur, py = v0 * Math.sin(th) * cur - 0.5 * g * cur * cur;
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(px), Y(py), 5, 0, Math.PI * 2); ctx.fill();

// landing point and distance along slope
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(X(xL), Y(yL), 3.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("lands here", X(xL) - 30, Y(yL) + (ph >= 0 ? -10 : 18));
ctx.fillStyle = C.figure;
var lx = xmin + (xmax - xmin) * 0.8;
ctx.fillText("slope", X(lx), Y(lx * Math.tan(ph)) + 16);
ctx.fillStyle = C.ink;
ctx.fillText("launch", X(0) + 4, Y(0) - 8);

if (valid) {
  out.note = "distance along slope L = " + Math.abs(L).toFixed(2) + " m, flight time " + tLand.toFixed(2) + " s";
} else {
  out.note = "at this angle the ball never comes back to the slope: aim higher above it";
}

var g = 9.8, v0 = 20, th = 50 * Math.PI / 180;
var T = 2 * v0 * Math.sin(th) / g;
var R = v0 * v0 * Math.sin(2 * th) / g;
var Hm = v0 * v0 * Math.sin(th) * Math.sin(th) / (2 * g);
var pad = 36;
var sc = Math.min((W - pad * 2) / (R * 1.05), (H - pad * 2) / (Hm * 1.7));
function X(x) { return pad + x * sc; }
function Y(y) { return H - pad - y * sc; }

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;

// ground
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();

// path
ctx.strokeStyle = C.rule;
ctx.lineWidth = 2;
ctx.beginPath();
for (var s = 0; s <= T; s += T / 120) {
  var xx = v0 * Math.cos(th) * s, yy = v0 * Math.sin(th) * s - 0.5 * g * s * s;
  if (s === 0) ctx.moveTo(X(xx), Y(yy)); else ctx.lineTo(X(xx), Y(yy));
}
ctx.stroke();
ctx.lineWidth = 1;

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var a = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 7 * Math.cos(a - 0.4), y1 - 7 * Math.sin(a - 0.4));
  ctx.lineTo(x1 - 7 * Math.cos(a + 0.4), y1 - 7 * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

var marks = [0, T / 2, T];
var names = ["launch", "top", "landing"];
for (var k = 0; k < 3; k++) {
  var tk = marks[k];
  var xk = v0 * Math.cos(th) * tk, yk = v0 * Math.sin(th) * tk - 0.5 * g * tk * tk;
  var vx = v0 * Math.cos(th), vy = v0 * Math.sin(th) - g * tk;
  var Px = X(xk), Py = Y(yk);
  ctx.fillStyle = C.ink;
  ctx.beginPath(); ctx.arc(Px, Py, 4, 0, Math.PI * 2); ctx.fill();
  // components
  arrow(Px, Py, Px + vx * 2.2, Py, C.accent);
  if (Math.abs(vy) > 0.3) arrow(Px, Py, Px, Py - vy * 2.2, C.figure);
  ctx.strokeStyle = C.rule;
  ctx.setLineDash([2, 3]);
  ctx.beginPath(); ctx.moveTo(Px, Py); ctx.lineTo(Px + vx * 2.2, Py - vy * 2.2); ctx.stroke();
  ctx.setLineDash([]);
  ctx.fillStyle = C.ink;
  ctx.fillText(names[k], Px - 12, Py + 18);
  ctx.fillStyle = C.accent;
  ctx.fillText("vx = " + vx.toFixed(1), Px + vx * 2.2 + 4, Py + 4);
  if (Math.abs(vy) > 0.3) {
    ctx.fillStyle = C.figure;
    ctx.fillText("vy = " + vy.toFixed(1), Px + 5, Py - vy * 2.2 + (vy > 0 ? -4 : 12));
  } else {
    ctx.fillStyle = C.figure;
    ctx.fillText("vy = 0", Px + 5, Py - 8);
  }
}

// height and range labels
ctx.strokeStyle = C.faint;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(R / 2), Y(0)); ctx.lineTo(X(R / 2), Y(Hm)); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("H = " + Hm.toFixed(1) + " m", X(R / 2) + 6, Y(Hm / 2));
ctx.fillText("R = " + R.toFixed(1) + " m", X(R / 2) - 28, Y(0) + 16);
ctx.fillText("v0 = 20 m/s at 50 deg, g = 9.8 m/s^2", pad, pad - 14);

out.note = "vx is the same at all three points; vy flips sign and keeps its size by landing";
